package com.lolfm.composition;
import com.lolfm.champion.*;import java.util.*;
public final class TeamCompositionAggregator{public TeamCompositionCoverage aggregate(TeamCompositionLineup lineup,Map<ChampionRoleKey,ChampionCompositionProfile>profiles){Objects.requireNonNull(lineup);Map<ChampionRoleKey,ChampionCompositionProfile>p=Map.copyOf(profiles);for(var k:lineup.championsByPosition().values())if(!p.containsKey(k)||!p.get(k).championRoleKey().equals(k))throw new IllegalArgumentException("Missing lineup profile "+k);EnumMap<CompositionCapability,CapabilityCoverage>out=new EnumMap<>(CompositionCapability.class);for(var c:CompositionCapability.values())out.put(c,coverage(c,lineup,p));int physical=0,magic=0,trueDamage=0;for(var k:lineup.championsByPosition().values()){var d=p.get(k).damageProfile();physical+=d.physicalThreat();magic+=d.magicThreat();trueDamage+=d.trueDamageThreat();}int total=physical+magic+trueDamage;DamageChannelCoverage damage=new DamageChannelCoverage(physical,magic,trueDamage,total==0?0.0:physical/(double)total,total==0?0.0:magic/(double)total,total==0?0.0:trueDamage/(double)total,total>0);return new TeamCompositionCoverage(out,damage);}private CapabilityCoverage coverage(CompositionCapability c,TeamCompositionLineup l,Map<ChampionRoleKey,ChampionCompositionProfile>p){var type=CompositionAggregationPolicy.type(c);List<Item>items=l.championsByPosition().values().stream().map(k->new Item(k,p.get(k).capability(c))).sorted(Comparator.comparingInt(Item::raw).reversed().thenComparing(x->x.key().stableId())).toList();List<CapabilityContributor>cs=new ArrayList<>();double sum=0;for(int i=0;i<items.size();i++){var x=items.get(i);double n=x.raw()/20d,w=CompositionAggregationPolicy.weight(type,i+1),v=zero(n*w);sum+=v;cs.add(new CapabilityContributor(x.key(),x.key().position(),x.raw(),zero(n),i+1,w,v));}sum=zero(Math.max(0,Math.min(1,sum)));return new CapabilityCoverage(c,type,sum,cs);}private static double zero(double v){return v==0?0.0:v;}private record Item(ChampionRoleKey key,int raw){}}
